@import url("https://fonts.googleapis.com/css2?family=Inter:wght@400;600;700;800&display=swap");
html,
body,
#root {
  margin: 0;
  padding: 0;
  width: 100%;
  min-height: 0;
  min-width: 0;
  background: transparent;
  font-family: "Inter", system-ui, -apple-system, sans-serif;
  box-sizing: border-box;
}

.widget-container {
  width: 100%;
  min-height: 0;
  min-width: 0;
  background: #ffffff;
  box-sizing: border-box;
  padding: 0;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  justify-content: flex-start;
}

.welcome-header {
  padding: 0;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  justify-content: flex-start;
  gap: 0.1em;
  text-align: left;
}

.eyebrow-row {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 12px;
  margin: 0 0 4px 0;
}

.eyebrow {
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.5px;
  text-transform: uppercase;
  color: #2563eb;
  margin: 0;
}

.badge {
  display: inline-flex;
  align-items: center;
  background-color: #1e293b;
  color: #94a3b8;
  font-size: 11px;
  font-weight: 600;
  padding: 3px 10px;
  border-radius: 9999px;
  white-space: nowrap;
}

.badge-count {
  color: #10b981;
  font-weight: 700;
  margin-left: 4px;
}

.main-title {
  font-size: 32px;
  font-weight: 800;
  line-height: 1.1;
  color: #0f172a;
  margin: 0 0 4px 0;
  letter-spacing: -0.5px;
  word-break: break-word;
  max-width: 95vw;
  text-align: left;
}

.subtitle {
  font-size: 16px;
  font-weight: 500;
  line-height: 1.5;
  color: #94a3b8;
  margin: 0;
  word-break: break-word;
  max-width: 95vw;
  text-align: left;
}

