import React, { useState, useEffect } from 'https://cdn.jsdelivr.net/npm/react@18.2.0/+esm';
import ReactDOM from 'https://cdn.jsdelivr.net/npm/react-dom@18.2.0/+esm';

function WelcomeHeader() {
  const [model, setModel] = useState(appsmith.model || {});

  useEffect(() => {
    appsmith.onModelChange((newModel) => {
      if (newModel) setModel(newModel);
    });
  }, []);

  const {
    department = "SYSTEM",
    userName = "User",
    welcomeMessage = "Welcome",
    subtitle = "Loading your dashboard...",
    totalPrCount
  } = model;

  return (
    <div className="widget-container">
      <div className="welcome-header">
        <div className="eyebrow-row">
          <div className="eyebrow">{department}</div>
          {totalPrCount !== undefined && totalPrCount !== null && totalPrCount !== "" && (
            <div className="badge">
              Total PR Count: <span className="badge-count">{totalPrCount}</span>
            </div>
          )}
        </div>
        <h1 className="main-title">{welcomeMessage}, {userName}.</h1>
        <p className="subtitle">{subtitle}</p>
      </div>
    </div>
  );
}

appsmith.onReady(() => {
  document.documentElement.style.overflow = 'hidden';
  document.body.style.overflow = 'hidden';
  ReactDOM.render(<WelcomeHeader />, document.getElementById('root'));
});
